<?php
namespace App\Http\Controllers; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash;
class AuthController extends Controller {public function show(){return view('auth.login');} public function login(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required']); if(Auth::attempt($data)){$r->session()->regenerate();return redirect()->intended('/');} return back()->withErrors(['email'=>'Email ya password ghalat hai.'])->onlyInput('email');} public function setup(){if(User::exists())return redirect('/login')->with('error','Admin account pehle se maujood hai.');return view('auth.setup');} public function createAdmin(Request $r){if(User::exists())abort(403);$d=$r->validate(['name'=>'required|max:120','email'=>'required|email|unique:users,email','password'=>'required|min:8|confirmed']);User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password'])]);return redirect('/login')->with('success','Admin account ban gaya. Login karein.');} public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}}
